mapper.select:
SELECT DISTINCT BSIH.BOOKSET_ID, BB.BOOKSET_NAME, BSIH.SUBJECT_INTERNAL_CODE, BSI.SUBJECT_INTERNAL_NAME, BSI.SUBJECT_LEVEL, BSI.SUBJECT_TYPE, BSI.ACC_FLAG, BSIDR.GEN_DETSUB_RULE FROM BOK_SUBJECT_INTERNAL_HAND BSIH LEFT JOIN BOK_BOOKSET BB ON BSIH.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_SUBJECT_INTERNAL BSI ON BSIH.SUBJECT_INTERNAL_CODE = BSI.SUBJECT_INTERNAL_CODE LEFT JOIN BOK_SUBJECT_INTERNAL_RULE BSIDR ON BSIH.SUBJECT_INTERNAL_CODE=BSIDR.SUBJECT_INTERNAL_CODE AND BSIH.BOOKSET_ID=BSIDR.BOOKSET_ID WHERE 1=1
AND BSIH.BOOKSET_ID=#{booksetId}
and BSIH.SUBJECT_INTERNAL_CODE IN
#{subjectInternalCode}

SELECT BSIH.HAND_CODE, SD.DICT_CNNAME AS HAND_NAME,BSIH.STATUS FROM BOK_SUBJECT_INTERNAL_HAND BSIH LEFT JOIN SYS_DATADICT SD ON BSIH.HAND_CODE = SD.DICT_CODE where 1=1
AND BSIH.BOOKSET_ID=#{booksetId}
AND BSIH.SUBJECT_INTERNAL_CODE=#{subjectInternalCode}
order by BSIH.HAND_CODE

SELECT BSIH.HAND_CODE, SD.DICT_CNNAME AS HAND_NAME,BSIH.STATUS
FROM BOK_SUBJECT_INTERNAL_HAND BSIH
LEFT JOIN SYS_DATADICT SD
ON BSIH.HAND_CODE = SD.DICT_CODE
where 1=1

    AND BSIH.BOOKSET_ID=#{booksetId}


    AND BSIH.SUBJECT_INTERNAL_CODE=#{subjectInternalCode}


    AND BSIH.STATUS=#{status}

order by BSIH.HAND_CODE

mapper.insert:
MERGE INTO BOK_SUBJECT_INTERNAL_HAND bbd using (
#{item.booksetId,jdbcType=VARCHAR} BOOKSET_ID, #{item.subjectInternalCode,jdbcType=VARCHAR} SUBJECT_INTERNAL_CODE, #{item.handCode,jdbcType=VARCHAR} HAND_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME
) datas on (bbd.BOOKSET_ID = datas.BOOKSET_ID and bbd.SUBJECT_INTERNAL_CODE = datas.SUBJECT_INTERNAL_CODE AND bbd.HAND_CODE=datas.HAND_CODE) WHEN MATCHED THEN UPDATE set bbd.UPDATE_TIME = SYSDATE,bbd.UPDATE_USER = datas.UPDATE_USER,bbd.STATUS=datas.STATUS WHEN NOT MATCHED THEN INSERT ( BOOKSET_ID, SUBJECT_INTERNAL_CODE, HAND_CODE, STATUS, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ( datas.BOOKSET_ID, datas.SUBJECT_INTERNAL_CODE, datas.HAND_CODE, datas.STATUS, datas.CREATE_USER, datas.CREATE_DEPT, datas.CREATE_TIME, datas.UPDATE_USER, datas.UPDATE_TIME )
